export const exerciseById=id=>exercises.find(e=>e.id===id);
export function alternatives(exercise,equipment=[]){return exercises.filter(e=>e.id!==exercise.id&&e.category===exercise.category&&(e.pattern===exercise.pattern||e.primary.some(g=>exercise.primary.includes(g)))&&(!equipment.length||e.equipment.every(x=>x==='bodyweight'||equipment.includes(x)))).sort((a,b)=>(b.pattern===exercise.pattern)-(a.pattern===exercise.pattern)).slice(0,6)}
